const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Polygon covering the confluence of the Elkhorn and Platte Rivers, west of Omaha, Nebraska.
  // This area was significantly affected by the March 2019 Midwest floods.
  const roi = ee.Geometry.Polygon([[
    [-96.45, 41.20],
    [-96.20, 41.20],
    [-96.20, 41.35],
    [-96.45, 41.35],
    [-96.45, 41.20]
  ]]);

  const startDate2018 = '2018-03-01';
  const endDate2018 = '2018-03-31';
  const startDate2019 = '2019-03-15'; // A small window around the specific date
  const endDate2019 = '2019-03-18';

  // 2. Data Acquisition & Check
  // Using Sentinel-1 SAR as it is not affected by clouds, which is crucial for flood mapping.
  // 'VV' polarization is sensitive to surface water.
  const getS1Collection = (startDate, endDate) => {
    return ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .select('VV');
  };

  const col2018 = getS1Collection(startDate2018, endDate2018);
  const col2019 = getS1Collection(startDate2019, endDate2019);

  const count2018 = col2018.size().getInfo();
  const count2019 = col2019.size().getInfo();

  if (count2018 === 0 || count2019 === 0) {
    console.log(`Image Count 2018: ${count2018}`);
    console.log(`Image Count 2019: ${count2019}`);
    console.log("Empty Collection: No Sentinel-1 images found for one or both periods.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Create median composites to get a representative image for each period.
  const image2018 = col2018.median().clip(roi);
  const image2019 = col2019.median().clip(roi);

  // Water has low backscatter in SAR imagery. A threshold of -16 dB is a common value for water detection.
  const waterThreshold = -16;
  const waterMask2018 = image2018.lt(waterThreshold);
  const waterMask2019 = image2019.lt(waterThreshold);

  // 4. Calculation
  // Calculate the area of water in square kilometers for each period.
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Area in sq km
  const waterArea2018Image = waterMask2018.multiply(pixelArea);
  const waterArea2019Image = waterMask2019.multiply(pixelArea);

  const scale = 100; // Scale appropriate for Sentinel-1
  const reducer = ee.Reducer.sum();

  const waterStats2018 = waterArea2018Image.reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  });

  const waterStats2019 = waterArea2019Image.reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: scale,
    maxPixels: 1e9
  });

  const area2018 = waterStats2018.get('VV').getInfo();
  const area2019 = waterStats2019.get('VV').getInfo();

  // 5. Validation & Final Answer
  if (area2018 === null || area2019 === null) {
    console.log(`2018 Area (sq km): ${area2018}`);
    console.log(`2019 Area (sq km): ${area2019}`);
    console.log("Calculation resulted in null, indicating an issue.");
    console.log("C3");
    return;
  }

  const totalPixels2018 = waterMask2018.reduceRegion({reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: 1e9}).get('VV').getInfo();
  const totalPixels2019 = waterMask2019.reduceRegion({reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: 1e9}).get('VV').getInfo();

  if (totalPixels2018 === 0 && totalPixels2019 === 0) {
      console.log(`2018 Valid Pixels: ${totalPixels2018}`);
      console.log(`2019 Valid Pixels: ${totalPixels2019}`);
      console.log("No valid pixels found in the region for either period.");
      console.log("C2");
      return;
  }


  console.log(`Image Count 2018: ${count2018}`);
  console.log(`Image Count 2019: ${count2019}`);
  console.log(`2018 Surface Water Extent (sq km): ${area2018.toFixed(2)}`);
  console.log(`2019 Surface Water Extent (sq km): ${area2019.toFixed(2)}`);

  if (area2019 > area2018) {
    console.log("Evidence: Water extent in March 2019 is greater than in March 2018.");
    console.log("A");
  } else {
    console.log("Evidence: Water extent in March 2019 is not greater than in March 2018.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
